# 修改高亮逻辑，让选中节点的所有下游连接线都高亮
patch(
    path="/Users/macpro/antoken/frontend/src/components/canvas/WorkflowCanvas.tsx",
    old_string="""      <ReactFlow
        nodes={nodes}
        edges={edges.map(edge => ({
          ...edge,
          style: {
            ...edge.style,
            stroke: (selectedNodeId && (edge.source === selectedNodeId || edge.target === selectedNodeId))
              ? "#ffffff"
              : "rgba(255,255,255,0.4)",
            strokeWidth: (selectedNodeId && (edge.source === selectedNodeId || edge.target === selectedNodeId))
              ? 2
              : 1.5,
          },
        }))}""",
    new_string="""      <ReactFlow
        nodes={nodes}
        edges={edges.map(edge => {
          // 获取所有下游节点
          const getDownstreamNodes = (nodeId: string): string[] => {
            const directTargets = edges.filter(e => e.source === nodeId).map(e => e.target);
            const allTargets = [...directTargets];
            directTargets.forEach(targetId => {
              allTargets.push(...getDownstreamNodes(targetId));
            });
            return allTargets;
          };

          const isHighlighted = selectedNodeId && (
            edge.source === selectedNodeId || 
            edge.target === selectedNodeId ||
            getDownstreamNodes(selectedNodeId).includes(edge.source) ||
            getDownstreamNodes(selectedNodeId).includes(edge.target)
          );

          return {
            ...edge,
            style: {
              ...edge.style,
              stroke: isHighlighted ? "#ffffff" : "rgba(255,255,255,0.2)",
              strokeWidth: isHighlighted ? 2 : 1.5,
            },
          };
        })}"""
)

