{"content":""use client";

import React, { useState } from "react";
import { useReactFlow } from "@xyflow/react";
import { useWorkflowStore } from "@/stores/workflowStore";

export default function CanvasControls() {
  const { fitView, zoomIn, zoomOut } = useReactFlow();
  const { 
    miniMapVisible, toggleMiniMap, 
    undo, redo, undoStack, redoStack,
    togglePropertyPanel, propertyPanelOpen
  } = useWorkflowStore();

  const [hoveredBtn, setHoveredBtn] = useState<string | null>(null);

  const btnStyle = (id: string, active?: boolean): React.CSSProperties => ({
    width: 32,
    height: 32,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    fontSize: 13,
    color: active ? "#ffffff" : hoveredBtn === id ? "#ffffff" : "#8a8f98",
    background: active ? "rgba(255,255,255,0.1)" : hoveredBtn === id ? "rgba(255,255,255,0.05)" : "transparent",
    border: "none",
    borderRadius: 6,
    cursor: "pointer",
    transition: "all 0.15s ease",
  });

  const containerStyle: React.CSSProperties = {
    background: "rgba(15,16,17,0.9)",
    border: "1px solid rgba(255,255,255,0.08)",
    backdropFilter: "blur(12px)",
  };

  return (
    <div className="absolute bottom-4 left-4 flex items-center gap-2 z-10 animate-fade-in">
      {/* 缩放控制 */}
      <div className="flex items-center gap-0.5 px-1 py-1 rounded-lg" style={containerStyle}>
        <button
          style={btnStyle("zoomIn")}
          onClick={() => zoomIn()}
          title="放大 (Ctrl +)"
          onMouseEnter={() => setHoveredBtn("zoomIn")}
          onMouseLeave={() => setHoveredBtn(null)}
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M8 4v8M4 8h8" />
          </svg>
        </button>
        <button
          style={btnStyle("zoomOut")}
          onClick={() => zoomOut()}
          title="缩小 (Ctrl -)"
          onMouseEnter={() => setHoveredBtn("zoomOut")}
          onMouseLeave={() => setHoveredBtn(null)}
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M4 8h8" />
          </svg>
        </button>
        <div className="w-px h-4 mx-0.5" style={{ background: "rgba(255,255,255,0.08)" }} />
        <button
          style={btnStyle("fitView")}
          onClick={() => fitView({ padding: 0.2 })}
          title="适应视图 (Ctrl+0)"
          onMouseEnter={() => setHoveredBtn("fitView")}
          onMouseLeave={() => setHoveredBtn(null)}
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <rect x="2" y="2" width="12" height="12" rx="2" />
            <path d="M2 6h12M6 2v12" />
          </svg>
        </button>
      </div>

      {/* 撤销/重做 */}
      <div className="flex items-center gap-0.5 px-1 py-1 rounded-lg" style={containerStyle}>
        <button
          style={{
            ...btnStyle("undo", false),
            opacity: undoStack.length === 0 ? 0.3 : 1,
            cursor: undoStack.length === 0 ? "default" : "pointer",
          }}
          disabled={undoStack.length === 0}
          onClick={undo}
          title="撤销 (Ctrl+Z)"
          onMouseEnter={() => { if (undoStack.length > 0) setHoveredBtn("undo"); }}
          onMouseLeave={() => setHoveredBtn(null)}
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M4 8h8M4 8l3-3M4 8l3 3" />
          </svg>
        </button>
        <button
          style={{
            ...btnStyle("redo", false),
            opacity: redoStack.length === 0 ? 0.3 : 1,
            cursor: redoStack.length === 0 ? "default" : "pointer",
          }}
          disabled={redoStack.length === 0}
          onClick={redo}
          title="重做 (Ctrl+Shift+Z)"
          onMouseEnter={() => { if (redoStack.length > 0) setHoveredBtn("redo"); }}
          onMouseLeave={() => setHoveredBtn(null)}
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M12 8H4M12 8l-3-3M12 8l-3 3" />
          </svg>
        </button>
      </div>

      {/* 视图控制 */}
      <div className="flex items-center gap-0.5 px-1 py-1 rounded-lg" style={containerStyle}>
        <button
          style={btnStyle("miniMap", miniMapVisible)}
          onClick={toggleMiniMap}
          title="小地图"
          onMouseEnter={() => setHoveredBtn("miniMap")}
          onMouseLeave={() => setHoveredBtn(null)}
        >
